// WF-4 guard — validate approved candidate
const state = $input.first().json;
if (!state || state.schema_version !== 1) throw new Error(`WF-4: invalid schema_version ${JSON.stringify(state?.schema_version)}`);
const c = state.candidate;
if (!c || !c.tool_name || !c.code) throw new Error('WF-4: candidate.tool_name/code missing');
if (!c.input_schema) throw new Error('WF-4: candidate.input_schema missing');
// stash state for next nodes
return [{ json: { state, candidate: c } }];

// WF-4 Tool Factory — builds a DynamicStructuredTool
// The tool's func is a THIN HTTP CLIENT to sandbox-runner (ADR-2).
// No generated code ever runs in this Code Node.
//
// n8n LangChain Code node quirk: tools built here must be returned as `tools` for the Agent to see.
// Sprint 1 sketch: we build ONE tool from candidate and emit it. The Orchestrator's Agent will have it.
// If n8n's LangChain Code node version drift blocks this (Risk R4), fallback is a generic
// run_approved_tool(tool_name, input) dispatcher — architecture preserved.
const { DynamicStructuredTool } = require('@langchain/core/tools');
const { z } = require('zod');

const candidate = $input.first().json.candidate;
const state = $input.first().json.state;

// Build zod schema from candidate.input_schema — Sprint 1 is {input: string}
// Generic: map each key to z.string()
const schemaShape = {};
for (const [k, v] of Object.entries(candidate.input_schema)) {
  // v is a type hint string like "string" — map to z.string()
  schemaShape[k] = z.string().describe(`input field ${k}`);
}
const schema = z.object(schemaShape);

const sandboxUrl = process.env.SANDBOX_RUNNER_URL || $env.SANDBOX_RUNNER_URL || 'http://sandbox-runner:8000';

const tool = new DynamicStructuredTool({
  name: candidate.tool_name,
  description: candidate.description || `Tool ${candidate.tool_name} — input: ${JSON.stringify(candidate.input_schema)}`,
  schema: schema,
  func: async (args) => {
    // Thin HTTP client — never eval candidate.code here
    const input = args.input ?? args.text ?? JSON.stringify(args);
    const body = JSON.stringify({
      language: candidate.language || 'python',
      code: candidate.code,
      input: String(input),
      timeout_s: 10,
      memory_mb: 256
    });
    // Use n8n helpers if available, fallback to fetch
    let data;
    let httpStatus = 200;
    try {
      if (typeof this !== 'undefined' && this.helpers && this.helpers.httpRequest) {
        data = await this.helpers.httpRequest({ method: 'POST', url: `${sandboxUrl}/execute`, body: JSON.parse(body), json: true });
      } else if (typeof $http !== 'undefined' && $http.request) {
        const r = await $http.request({ method: 'POST', url: `${sandboxUrl}/execute`, body: JSON.parse(body), returnFullResponse: true });
        data = r.body; httpStatus = r.statusCode || 200;
      } else {
        const resp = await fetch(`${sandboxUrl}/execute`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: body });
        data = await resp.json(); httpStatus = resp.status;
        if (!resp.ok) return `tool error: http ${resp.status} — ${JSON.stringify(data)}`;
      }
    } catch (e) {
      // Last resort: use Node http directly
      const http = require('http');
      data = await new Promise((resolve, reject) => {
        const u = new URL(`${sandboxUrl}/execute`);
        const req = http.request({ hostname: u.hostname, port: u.port || 80, path: u.pathname, method: 'POST', headers: { 'Content-Type': 'application/json', 'Content-Length': Buffer.byteLength(body) } }, (res) => {
          let d=''; res.on('data', c=>d+=c); res.on('end', ()=>{ try{ resolve(JSON.parse(d)); }catch(e){ resolve({stdout:d}); } });
        });
        req.on('error', reject); req.write(body); req.end();
      });
    }
    if (httpStatus < 200 || httpStatus >= 300) {
      return `tool error: http ${httpStatus} — ${JSON.stringify(data)}`;
    }
    if (data.exit_code !== 0 || data.timed_out) {
      return `tool error: exit ${data.exit_code} — stderr: ${(data.stderr||'').slice(0,500)}`;
    }
    // Return stdout as tool output for the Agent to use
    return (data.stdout || '').trim();
  }
});

// For demo visibility, also test-invoke the tool once with the state's goal-derived input
// so the workflow's output already contains the result even before the Orchestrator's Agent calls it.
const demoInput = (state.test && state.test.runs && state.test.runs[0] && state.test.runs[0].input) || state.goal || 'hello';
// Extract the last word as the string to reverse (walking skeleton heuristic)
let toolInput = demoInput;
// If goal is "reverse this string: hello" → tool should get "hello"
const m = /:\s*"?([^"\n]+)"?\s*$/.exec(demoInput);
if (m) toolInput = m[1].trim();
else {
  const words = demoInput.trim().split(/\s+/);
  toolInput = words[words.length-1] || demoInput;
}
let demoOutput = null;
let demoError = null;
try {
  demoOutput = await tool.invoke({ input: toolInput });
} catch (e) {
  demoError = String(e).slice(0,500);
}

// Return state augmented with factory result
return [{
  json: {
    ...state,
    tool_factory: {
      tool_name: tool.name,
      description: tool.description,
      demo_input: toolInput,
      demo_output: demoOutput,
      demo_error: demoError
    },
    outcome: {
      ...(state.outcome||{}),
      status: demoError ? 'failed' : 'deployed',
      final_answer: demoOutput || state.outcome?.final_answer || ''
    }
  },
  // Also expose the tool for n8n Agent wiring if this workflow is used as a Tool
  // (LangChain Code node convention: return tools in a separate field — we emulate it)
  pairedItem: { item: 0 }
}];
